# 配置文件（与脚本/exe 同目录）
def _config_path():
    if getattr(sys, 'frozen', False):
        d = os.path.dirname(os.path.abspath(sys.executable))
    else:
        d = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(d, 'zzz_fix_设置.json')


def _load_config():
    try:
        with open(_config_path(), encoding='utf-8') as f:
            return json.load(f)
    except Exception:
        return {}


def _save_config(cfg):
    try:
        with open(_config_path(), 'w', encoding='utf-8') as f:
            json.dump(cfg, f, ensure_ascii=False, indent=2)
    except OSError as e:
        print('保存设置失败: {}'.format(e))


def _doc_text(fname, embedded):
    """读取随包文档：程序目录存在 fname 时优先读文件（便于作者直接改 txt 维护），
    打包后无 txt 时退回内嵌文本。"""
    try:
        if getattr(sys, 'frozen', False):
            d = os.path.dirname(os.path.abspath(sys.executable))
        else:
            d = os.path.dirname(os.path.abspath(__file__))
        with open(os.path.join(d, fname), encoding='utf-8') as f:
            data = f.read()
            if data.strip():
                return data
    except Exception:
        pass
    return embedded


# ================= 自动更新核心（Gitee 优先，GitHub 兜底） =================
# 版本号格式：数字+可选字母后缀，如 3.1 / 3.1C / 3.10。比较按 (数字, 后缀) 逐段进行。
def _upd_repos():
    """(host, repo) 列表，按 Gitee→GitHub 顺序；设置文件可覆盖代码常量"""
    cfg = _load_config()
    pairs = (('gitee', cfg.get('update_gitee_repo') or GITEE_REPO),
             ('github', cfg.get('update_github_repo') or GITHUB_REPO))
    return [(h, r) for h, r in pairs if r]


def _upd_configured():
    return bool(_upd_repos())


def _ver_key(v):
    """版本串→可比较键。例：3.1C → 数字按位宽补零 + 小写后缀，字符串可直接比较"""
    m = re.search(r'(\d+(?:\.\d+)*[A-Za-z]*)', str(v))
    s = m.group(1) if m else re.sub(r'[^0-9A-Za-z.]', '', str(v))
    key = []
    for part in s.split('.'):
        mm = re.match(r'^(\d+)([A-Za-z]*)$', part)
        if mm:
            key.append('{:012d}{}'.format(int(mm.group(1)), mm.group(2).lower()))
        else:
            key.append(part.lower())
    return tuple(key)


def _version_greater(new_ver, cur_ver):
    """new 版本号严格大于 cur 才返回 True（3.1C > 3.1B；3.1 < 3.1A）"""
    return _ver_key(new_ver) > _ver_key(cur_ver)


def _releases_page_url():
    """发布页地址（首选源），给用户自己去下压缩包用；没配仓库就回落到项目主页"""
    repos = _upd_repos()
    if repos:
        host, repo = repos[0]
        base = 'https://gitee.com/{}' if host == 'gitee' else 'https://github.com/{}'
        return '{}/releases'.format(base.format(repo))
    return URL_MOD_GUIDE


def _release_url(host, repo, tag, fname):
    """按 Release 下载链接规则拼直链（两者同构）"""
    q = lambda s: urllib.parse.quote(s, safe='')
    base = 'https://github.com/{}' if host == 'github' else 'https://gitee.com/{}'
    return '{}/releases/download/{}/{}'.format(base.format(q(repo)), q(tag), q(fname))


def _http_open(url, timeout=8.0, insecure_fallback=True):
    """urllib 封装：统一 UA。
    insecure_fallback=True 时，证书校验失败降级为不校验重试一次（无 ca 包的旧环境）。
    【下载程序本体一律用 False】：证书校验失败会被中间人利用 —— 他先让校验失败，
    再喂一个改过的包，程序就会覆盖自身。查版本这种只读接口才允许降级。"""

    def _req():
        return urllib.request.Request(url, headers={
            'User-Agent': 'ZZZ-Fix-{}/1.0 (Windows)'.format(APP_VERSION),
            'Accept': 'application/json, */*'})

    try:
        return urllib.request.urlopen(_req(), timeout=timeout)
    except urllib.error.URLError as e:
        if insecure_fallback and isinstance(getattr(e, 'reason', None), ssl.SSLError):
            return urllib.request.urlopen(_req(), timeout=timeout,
                                          context=ssl._create_unverified_context())
        raise
    except ssl.SSLError:
        if not insecure_fallback:
            raise
        return urllib.request.urlopen(_req(), timeout=timeout,
                                      context=ssl._create_unverified_context())


def _http_json(url):
    with _http_open(url) as r:
        data = r.read()
    return json.loads(data.decode('utf-8-sig', 'replace'))


def _api_urls(host, repo):
    """一个源的几个接口：(latest 单条, 列表)。
    latest 是「最新 Release」直查 —— 不受分页影响，列表负责兜底
    （最新那版没传资产时要退到次新版本，latest 给不了）"""
    if host == 'gitee':
        base = 'https://gitee.com/api/v5/repos/{}'.format(
            urllib.parse.quote(repo, safe='/'))
        # Gitee 列表按时间正序、per_page 上限 100：给足才不漏最新版
        return base + '/releases/latest', base + '/releases?per_page=100'
    base = 'https://api.github.com/repos/{}'.format(
        urllib.parse.quote(repo, safe='/'))
    # GitHub 列表按时间倒序：最新几条就够
    return base + '/releases/latest', base + '/releases?per_page=20'


def _take_release(by_tag, order, it, host, repo, ext):
    """把一个 Release 的信息并进 by_tag（同一个 tag 在两个源出现过就合并）"""
    if not isinstance(it, dict):
        return
    tag = str(it.get('tag_name') or it.get('name') or '').strip()
    if not tag or it.get('draft'):
        return
    entry = by_tag.get(tag)
    if entry is None:
        entry = {'tag': tag, 'assets': [], 'alts': [], 'cand': [],
                 'pre': bool(it.get('prerelease')), 'all': [], 'body': ''}
        by_tag[tag] = entry
        order.append(tag)
    elif bool(it.get('prerelease')):
        entry['pre'] = True      # 有一边算预发布就按预发布处理
    body = str(it.get('body') or '').strip()
    if body and not entry['body']:
        entry['body'] = body     # Release 正文 = 更新内容（发布脚本从 CHANGELOG_TEXT 里截的）
    all_names = entry['all']
    for a in it.get('assets') or []:
        if not isinstance(a, dict):
            continue
        nm = str(a.get('name') or '')
        if not nm:
            nm = str(a.get('browser_download_url') or '').rsplit('/', 1)[-1]
        if nm not in all_names:
            all_names.append(nm)
        if not nm.lower().endswith(ext):
            continue
        if nm in (tag + '.zip', tag + '.tar.gz'):
            continue   # Gitee 自动附带的源码包，不是程序包
        url = a.get('browser_download_url') or _release_url(host, repo, tag, nm)
        cand = (nm, url, host)
        if cand not in entry['cand']:
            entry['cand'].append(cand)


def _list_releases():
    """查 Release：【每个源都查两条接口】—— 先直查「最新 Release」，再拉列表兜底。
    两个源都查是必须的：Gitee 漏发 / 挂了 / 最新那版没传资产时要用 GitHub 顶上。

    返回 (releases, errs)：
        releases = [{'tag', 'assets': [(名, 直链, host)], 'alts': [(名, 直链, host)],
                     'pre': 是否两边都算预发布, 'all': [该版本所有文件名]}]
        同一个 tag 只出现一次：先查到的源（Gitee）当主，另一个源的资产进 alts，
        下载失败时可以换着试；主源没资产时另一个源直接当主。
    全部源都失败则抛错（errs 是每个源的原因）"""
    ext = '.zip' if getattr(sys, 'frozen', False) else '.py'
    by_tag = {}
    order = []
    errs = []
    for host, repo in _upd_repos():
        latest_api, list_api = _api_urls(host, repo)
        got_latest = False
        try:
            _take_release(by_tag, order, _http_json(latest_api), host, repo, ext)
            got_latest = True
        except Exception as e:
            errs.append('{} latest: {}'.format(host, e))
        try:
            data = _http_json(list_api)
        except Exception as e:
            errs.append('{} 列表: {}'.format(host, e))
            continue
        if not isinstance(data, list) or not data:
            if not got_latest:
                errs.append('{}: 返回内容为空或异常'.format(host))
            continue
        for it in data:
            _take_release(by_tag, order, it, host, repo, ext)
    if not order:
        raise RuntimeError('；'.join(errs) or '更新源均无数据')
    # 候选排序：zzz_fix 开头的正经程序包优先，其余（改名过的老包）兜底；
    # 第一个当主用，其余留着下载失败时换（同名不同源 = Gitee 挂了换 GitHub）
    for tag in order:
        entry = by_tag[tag]
        cand = entry.pop('cand')
        pref = [c for c in cand if c[0].lower().startswith('zzz_fix')]
        rest = [c for c in cand if not c[0].lower().startswith('zzz_fix')]
        ranked = pref + rest
        entry['assets'] = ranked[:1]
        entry['alts'] = ranked[1:]
    return [by_tag[t] for t in order], errs


# 启动自动检查更新最多等这么久（秒），超时强制结束；手动检查不受限制
UPD_AUTO_TIMEOUT = 5.0


class UpdateCheckTimeout(Exception):
    """启动自动检查更新超时（后台请求还没回来，已放弃等待）"""


def _check_update_capped(timeout=None):
    """跑 check_update_now；超过 timeout 秒抛 UpdateCheckTimeout，timeout=None 不限时。
    超时后后台线程自己跑完就退出，结果直接丢弃（不影响主程序）。
    手动检查一律传 None —— 用户主动点的，等多久都行。"""
    if not timeout or timeout <= 0:
        return check_update_now()
    box = {}

    def _run():
        try:
            box['r'] = check_update_now()
        except BaseException as e:
            box['e'] = e

    t = threading.Thread(target=_run, daemon=True)
    t.start()
    t.join(timeout)
    if t.is_alive():
        raise UpdateCheckTimeout('检查更新超过 {:g} 秒'.format(timeout))
    if 'e' in box:
        raise box['e']
    return box['r']


def check_update_now():
    """查是否有更新。返回 (info, note)：
    info 非空 = 发现新版，含 new/old/fname/url/urls（urls 是同一个包的各源直链，
    第一个是首选源，下载失败按顺序换，Gitee 挂了就用 GitHub）；
    info 为空且 note 非空 = 有说明（如仓库未配置资产）；均空 = 已是最新。异常直接抛。"""
    if not _upd_configured():
        return None, '尚未配置更新仓库：请填写代码顶部 GITEE_REPO / GITHUB_REPO，或设置文件 update_gitee_repo / update_github_repo'
    releases, _errs = _list_releases()
    # 先看正式版，再看预发布
    stable = [r for r in releases if not r['pre']]
    pool = stable or releases
    cand = None
    for rel in sorted(pool, key=lambda r: _ver_key(r['tag']), reverse=True):
        if rel['assets']:
            cand = rel
            break
    if cand is None:
        newest = max(pool, key=lambda r: _ver_key(r['tag']))
        ext = '.zip' if getattr(sys, 'frozen', False) else '.py'
        names = (newest['all'] or [])[:10]
        return None, ('最新版本 {} 的 Release 里没有本模式可用的资产（{}）。\n'
                      '该版本现有附件：{}').format(newest['tag'], ext,
                                                 '、'.join(names) or '无')
    tag = cand['tag']
    if not _version_greater(tag, APP_VERSION):
        return None, ''
    fname, url, host = cand['assets'][0]
    urls = [(host, url)] + [(h, u) for (n, u, h) in cand['alts'] if n == fname]
    flags = _upd_body_flags(cand.get('body'))
    return ({'new': tag, 'old': APP_VERSION, 'fname': fname, 'url': url,
             'urls': urls, 'body': cand.get('body') or '',
             'manual': flags['manual'],
             'kind': 'zip' if getattr(sys, 'frozen', False) else 'py'},
            None)


def _upd_body_flags(body):
    """解析 Release 正文里的约定标记。现在只认一个：
        [MANUAL]（也认中文 [手动安装]）—— 本版必须手动安装，不给自动更新。
    写法：正文里任意一行写上标记就行，后面跟给人看的手动安装步骤。
    返回 {'manual': bool}"""
    body = body or ''
    return {'manual': ('[MANUAL]' in body.upper()) or ('[手动安装]' in body)}


def _upd_body_lines(info, limit=40):
    """新版更新内容（Release 正文）拆成行，便于打印 / 入日志；没有就返回空列表"""
    body = (info or {}).get('body') or ''
    lines = [ln.rstrip() for ln in body.splitlines()]
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    if len(lines) > limit:
        lines = lines[:limit] + ['…（更多见发布页）']
    return lines


def _program_target():
    """当前运行的程序本体路径（exe 或本 .py）"""
    if getattr(sys, 'frozen', False):
        return os.path.abspath(sys.executable)
    return os.path.abspath(__file__)


def _save_downloaded(tmp_path, preferred):
    """把下载好的 tmp 文件改名为最终名。同名旧文件被占用（资源管理器/杀软锁定）时
    自动加序号换名（xxx.zip → xxx(2).zip），保证一定能落盘；返回实际路径"""
    base, ext = os.path.splitext(preferred)
    for i in range(100):
        dest = preferred if i == 0 else '{}({}){}'.format(base, i + 1, ext)
        try:
            if os.path.exists(dest):
                os.remove(dest)
            os.rename(tmp_path, dest)
            return dest
        except OSError:
            continue
    raise RuntimeError('下载文件被占用，无法写入最终文件名')


def _sha256_file(path):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        while True:
            chunk = f.read(1 << 20)
            if not chunk:
                break
            h.update(chunk)
    return h.hexdigest()


def _fetch_expected_sha(url):
    """取发布方随包放的 .sha256（同目录同名 + .sha256）。取不到 / 格式不对返回 None。
    内容是 64 位十六进制即可，允许「HASH」或「HASH  文件名」两种写法"""
    try:
        with _http_open(url + '.sha256', timeout=10.0, insecure_fallback=False) as r:
            text = r.read(4096).decode('utf-8-sig', 'replace')
    except Exception:
        return None
    m = re.search(r'\b([0-9a-fA-F]{64})\b', text)
    return m.group(1).lower() if m else None


def _download_file(url, tmp_path, pct_cb=None, cancel_cb=None):
    """流式下载到 tmp_path。取消回调返回 True 时中止；内容异常(HTML/过小)视为失败。
    发布方放了 .sha256 就校验（对不上直接弃包），没放就跳过并在返回的提示里说明。
    下载程序本体不允许「证书校验失败就降级」，见 _http_open。返回一句说明文字"""
    with _http_open(url, timeout=25.0, insecure_fallback=False) as r:
        total = None
        cl = r.headers.get('Content-Length')
        if cl and cl.isdigit():
            total = int(cl)
        done = 0
        with open(tmp_path, 'wb') as f:
            while True:
                if cancel_cb is not None and cancel_cb():
                    raise RuntimeError('已取消下载')
                chunk = r.read(65536)
                if not chunk:
                    break
                f.write(chunk)
                done += len(chunk)
                if pct_cb is not None and total:
                    pct_cb(max(0, min(99, done * 100 // total)))
    size = os.path.getsize(tmp_path)
    if size < 1024:
        raise RuntimeError('下载内容过小（{} 字节），链接可能失效'.format(size))
    with open(tmp_path, 'rb') as f:
        head = f.read(256).lower()
    if head.startswith(b'<!doctype') or head.startswith(b'<html') or b'not found' in head:
        raise RuntimeError('下载到的不是程序文件（可能地址错误或被网络拦截）')
    if total and size != total:
        raise RuntimeError('下载不完整（{}/{} 字节），请重试'.format(size, total))
    note = ''
    want = _fetch_expected_sha(url)
    if want:
        got = _sha256_file(tmp_path)
        if got != want:
            try:
                os.remove(tmp_path)     # 删的是刚下的临时文件
            except OSError:
                pass
            raise RuntimeError('下载校验没过（SHA256 对不上，文件可能损坏或被改动），已丢弃。'
                               '请重试或手动去发布页下载')
        note = '（已按发布方 SHA256 校验）'
    else:
        note = '（发布方没提供 .sha256，未校验内容完整性）'
    if pct_cb is not None:
        pct_cb(100)
    return note


def _download_with_fallback(info, tmp_path, pct_cb=None):
    """按 info['urls'] 顺序下载（Gitee 失败换 GitHub），全失败抛最后一个错。
    返回 (用到的 host 或 None, 提示文字)"""
    urls = info.get('urls') or [(None, info.get('url', ''))]
    last = None
    for host, url in urls:
        if not url:
            continue
        try:
            note = _download_file(url, tmp_path, pct_cb=pct_cb)
            return host, note
        except Exception as e:      # 换下一个源再试
            last = e
            try:
                if os.path.exists(tmp_path):
                    os.remove(tmp_path)
            except OSError:
                pass
    raise last if last else RuntimeError('没有可用的下载地址')


def _verify_package(path, info):
    """装之前先验包：包里的版本要对得上 Release 标的版本，清单上的文件要都在包里。
    不对就抛错 —— 这种包装完新版一启动就会被自己的完整性检查拦下，白装。
    返回一句说明（包里没有清单时说明未做这项校验）"""
    tag = re.sub(r'^[vV]', '', str(info.get('new') or '')).lower()
    if info.get('kind') != 'zip':
        try:
            with open(path, 'rb') as f:
                head = f.read(1 << 20).decode('utf-8', 'replace')
        except OSError as e:
            raise RuntimeError('读不了下载的文件：{}'.format(e))
        m = re.search(r"APP_VERSION\s*=\s*['\"]([^'\"]+)['\"]", head)
        if not m:
            raise RuntimeError('下载到的文件里没有 APP_VERSION，可能不是程序本体')
        ver = m.group(1)
        if tag and re.sub(r'^[vV]', '', ver).lower() != tag:
            raise RuntimeError('下载到的是 {} 版，Release 标的是 {}，对不上，不安装'
                               .format(ver, info.get('new')))
        return '（已核对版本 {}）'.format(ver)
    try:
        with zipfile.ZipFile(path) as z:
            names = set(n.rstrip('/') for n in z.namelist())
            if FILE_MANIFEST not in names:
                return '（包里没有 {}，跳过包内校验）'.format(FILE_MANIFEST)
            raw = z.read(FILE_MANIFEST).decode('utf-8', 'replace')
    except Exception as e:
        raise RuntimeError('压缩包打不开（下载不完整或不是 zip）：{}'.format(e))
    ver = None
    rels = []
    for ln in raw.splitlines():
        ln = ln.strip()
        if not ln:
            continue
        if ln.startswith('#'):
            parts = ln.split()
            if len(parts) >= 2:
                ver = parts[-1]
            continue
        rels.append(ln.replace('\\', '/').lstrip('/'))
    if tag and ver and re.sub(r'^[vV]', '', ver).lower() != tag:
        raise RuntimeError('压缩包里的清单是 {} 版，Release 标的是 {}，对不上，不安装'
                           .format(ver, info.get('new')))
    missing = [r for r in rels if r not in names]
    if missing:
        raise RuntimeError('压缩包不完整：少了 {} 个清单上的文件（如 {}）'
                           .format(len(missing), '、'.join(missing[:3])))
    if not ver and not rels:
        return '（包内清单是空的，跳过包内校验）'
    return '（已核对包内清单 {}：{} 个文件齐全）'.format(ver or '?', len(rels))


def _apply_install(tmp_path):
    """原子替换程序本体：旧文件改名 .old → 新文件就位。失败自动回滚。返回新程序路径"""
    tgt = _program_target()
    old = tgt + '.old'
    try:
        if os.path.exists(old):
            try:
                os.remove(old)
            except OSError:
                pass
        if os.path.exists(tgt):
            try:
                os.rename(tgt, old)
            except OSError as e:
                raise RuntimeError('无法替换正在运行的程序：{}。请关闭其他实例后重试'.format(e))
        try:
            os.rename(tmp_path, tgt)
        except OSError as e:
            # 新文件放不进 → 还原旧文件
            try:
                if os.path.exists(old) and not os.path.exists(tgt):
                    os.rename(old, tgt)
            except OSError:
                pass
            raise RuntimeError('安装新版本失败：{}'.format(e))
    finally:
        try:
            if os.path.exists(tmp_path):
                os.remove(tmp_path)
        except OSError:
            pass
    return tgt


def _program_dir():
    """程序所在目录（exe 或本 .py 所在文件夹）"""
    return os.path.dirname(_program_target())


def _rmtree_retry(p, max_sec=60.0):
    """删目录树；杀软扫描锁定时轮询重试（最多 max_sec 秒），超时才放弃静默"""
    waited = 0.0
    while True:
        try:
            shutil.rmtree(p)
            return
        except OSError:
            if not os.path.exists(p):
                return
            if waited >= max_sec:
                return
            time.sleep(0.5)
            waited += 0.5


def _relaunch_command():
    """重启命令：exe 直接重跑；py 用原解释器带上原参数"""
    tgt = _program_target()
    if getattr(sys, 'frozen', False):
        # 只把黑窗开关带回去：GUI 重启时不该把拖进来的路径再修一遍
        return [tgt] + (['--cli'] if _console_mode_requested() else [])
    return [sys.executable, tgt] + list(sys.argv[1:])


def _cleanup_stale_old():
    """下次启动时清理更新残留：.old（仅当新程序已就位才删，半途失败的留着可恢复）、
    安装器 cmd、下载 .part、未完成的 .upd_new 暂存"""
    tgt = _program_target()
    d = os.path.dirname(tgt)
    try:
        # 新本体已存在才删 .old；本体缺席说明上次替换没完成，保留 .old 供恢复
        if os.path.exists(tgt):
            old = tgt + '.old'
            if os.path.exists(old):
                os.remove(old)
            # 兼容清扫（曾用整目录改名方案）：残留的 F.old 新本体在时安全删
            old_dir = d + '.old'
            if os.path.isdir(old_dir):
                _rmtree_retry(old_dir)
    except OSError:
        pass
    for fn in ('.upd_apply.cmd', '.upd_extract.ps1', '.upd_new'):
        try:
            p = os.path.join(d, fn)
            if os.path.isdir(p):
                _rmtree_retry(p)
            elif os.path.exists(p):
                os.remove(p)
        except OSError:
            pass
    # 依赖目录已改名中文“依赖包勿删”（旧结构叫 _internal）：
    # 新版程序能跑起来 = 自己依赖目录在；残留的旧 _internal 确认后清理
    try:
        if getattr(sys, 'frozen', False):
            dep = os.path.join(d, DEP_DIR_NAME)
            if os.path.isdir(dep) and os.path.isdir(os.path.join(d, '_internal')):
                _rmtree_retry(os.path.join(d, '_internal'))
    except OSError:
        pass
    try:
        for fn in os.listdir(d):
            if fn.startswith('.update_') and fn.endswith('.part'):
                try:
                    os.remove(os.path.join(d, fn))
                except OSError:
                    pass
            elif fn == FILE_MANIFEST_PREV:   # 旧版本留下的对比清单，已不用
                try:
                    os.remove(os.path.join(d, fn))
                except OSError:
                    pass
    except OSError:
        pass


def _manifest_path(name):
    """清单文件路径：一律放程序目录（与 exe / 设置 json 同级）"""
    if getattr(sys, 'frozen', False):
        d = os.path.dirname(os.path.abspath(sys.executable))
    else:
        d = os.path.dirname(os.path.abspath(__file__))
    return os.path.join(d, name)


def _read_manifest(path):
    """读清单。首行 '# zzz_fix manifest v3.2E' 取版本，其余每行一个相对路径（/ 分隔）。
    读不到 / 打不开返回 (None, set())"""
    try:
        with open(path, encoding='utf-8') as f:
            lines = [ln.strip() for ln in f]
    except (OSError, UnicodeDecodeError):
        return None, set()
    ver = None
    paths = set()
    for ln in lines:
        if not ln:
            continue
        if ln.startswith('#'):
            parts = ln.split()
            if len(parts) >= 2:
                ver = parts[-1]
            continue
        paths.add(ln.replace('\\', '/').lstrip('/'))
    return ver, paths


def _runtime_ok_names():
    """程序目录里「本来就不在清单上、也不算异常」的运行时名字：
    设置文件、下载的更新包、更新脚本、临时文件、清单自身"""
    return {FILE_MANIFEST, FILE_MANIFEST_PREV, 'zzz_fix_设置.json',
            UPD_CMD_NAME, UPD_PS1_NAME, UPD_FAIL_MARK, UPD_TMP_DIR}


def _scan_program_dir():
    """每次启动检查程序目录：清单上的文件全在吗（少了）+ 有没有清单外的东西（多了）。
    【只检测，绝不删】：更新只做覆盖，目录里可能有用户自己的文件，程序无从分辨，
    所以一律留着，只提示、只拦启动。返回 (extra_files, extra_dirs, missing)；
    判断不了（独立版 / 源码模式）→ (None, None, None)。
    清单本身也算被检查的文件：主程序（onedir）旁边没有清单、或清单版本和程序对不上，
    一样按「不完整」拦下来 —— 不然删掉清单就能绕过检查"""
    root = os.path.dirname(_program_target())
    onedir = os.path.isdir(os.path.join(root, DEP_DIR_NAME))
    if not onedir:
        return None, None, None    # 独立版单文件 / 源码模式：本来就不带清单，不判断
    cur_ver, cur = _read_manifest(_manifest_path(FILE_MANIFEST))
    if not cur or cur_ver != APP_VERSION:
        return [], [], [FILE_MANIFEST]
    missing = sorted(rel for rel in cur
                     if not os.path.exists(os.path.join(root, *rel.split('/'))))
    ok = _runtime_ok_names()
    files, dirs = [], []
    try:
        entries = list(os.scandir(root))
    except OSError:
        return None, None, None
    for entry in entries:
        if entry.name in ok or entry.name.lower().endswith('.zip') \
                or entry.name.lower().endswith('.part'):
            continue   # 设置、更新包、更新脚本、下载临时文件：正常存在
        if entry.is_dir(follow_symlinks=False):
            # 顶层文件夹：清单里没有以它开头的条目 = 不是本程序的
            if not any(rel.split('/', 1)[0] == entry.name for rel in cur):
                dirs.append(entry.name)
            else:
                for dirpath, _dirnames, filenames in os.walk(entry.path):
                    for fn in filenames:
                        rel = os.path.relpath(os.path.join(dirpath, fn), root).replace(os.sep, '/')
                        if rel not in cur:
                            files.append(rel)
        else:
            if entry.name not in cur:
                files.append(entry.name)
    return sorted(files), sorted(dirs), missing


def _brief(items, limit=6):
    """列表写成「前几个 + 还有 N 个」的多行文本"""
    lines = ['    {}'.format(x) for x in items[:limit]]
    if len(items) > limit:
        lines.append('    …还有 {} 个'.format(len(items) - limit))
    return lines


def describe_dir_check(files, dirs, missing):
    """把检查结果写成提示文案；一切正常返回 ''"""
    if not files and not dirs and not missing:
        return ''
    lines = []
    if FILE_MANIFEST in missing:
        lines.append('文件清单 {} 缺失，或和当前程序版本对不上。'.format(FILE_MANIFEST))
    rest = [m for m in missing if m != FILE_MANIFEST]
    if rest:
        lines.append('缺失的程序文件 {} 个：'.format(len(rest)))
        lines.extend(_brief(rest))
    if files:
        lines.append('不属于本程序的文件 {} 个：'.format(len(files)))
        lines.extend(_brief(files))
    if dirs:
        lines.append('不属于本程序的文件夹 {} 个：'.format(len(dirs)))
        lines.extend(_brief(dirs))
    return '\n'.join(lines)


def dir_check_advice(files, dirs, missing):
    """给用户怎么办：缺文件就重新解压；多出东西就挪走或换空目录，程序不带着它们跑"""
    parts = []
    if FILE_MANIFEST in missing:
        parts.append('程序目录不完整：文件清单没了、或清单和程序不是同一版。\n'
                     '多半是没按压缩包完整解压，或者被手动动过。\n'
                     '处理办法：重新把新版的压缩包解压到一个【空文件夹】，用新目录里的程序。')
    elif missing:
        parts.append('程序文件少了：多半是没解压全、被杀毒软件隔离，或者被手动删过。\n'
                     '处理办法：重新把新版的压缩包解压到一个【空文件夹】，用新目录里的程序。')
    if files or dirs:
        parts.append('多出来的东西：程序不会自动删，也不会带着它们运行。\n'
                     '处理办法：把多出来的文件 / 文件夹挪走或删掉；想彻底干净就解压到一个'
                     '【空文件夹】再用。')
    return '\n\n'.join(parts)


UPD_CMD_NAME = '.upd_apply.cmd'
UPD_PS1_NAME = '.upd_extract.ps1'   # 旧版更新脚本，已不用；启动时顺手清掉残留
UPD_FAIL_MARK = '.upd_fail.txt'
UPD_TMP_DIR = '.upd_new'      # 更新暂存目录：新版先解到这里，核对过清单才动程序目录
FILE_MANIFEST = '.zzz_files.txt'        # 随包文件清单（打包时 build_version.py 生成，跟着 zip 发）
FILE_MANIFEST_PREV = '.zzz_files_prev.txt'  # 旧版本留下的对比清单；不再生成，启动时顺手清掉
DEP_DIR_NAME = '依赖包勿删'   # onedir 依赖目录名（与 一键打包发布.bat 的 --contents-directory 同步维护）


def _cmd_escape(p):
    """路径嵌入 .cmd 的 set 引号内仍会展开的字符只有 %；含 % 返回 None，调用方走手动兜底"""
    return p if '%' not in p else None


def _stage_update(zip_dest):
    """把新版 zip 解到程序目录下的暂存 .upd_new 并核对包内清单。
    解压用 Python 自带的 zipfile：同一个包实测 0.8 秒，PowerShell 的 Expand-Archive 要 13 秒。
    【此时旧程序还在跑，程序目录一个字节都没动】：解压失败 / 包不完整就抛错，
    调用方回退到手动更新指引，用户手上那份程序还是好的。
    返回暂存目录路径；失败抛 RuntimeError"""
    exe = _program_target()
    fdir = os.path.dirname(exe)            # 程序目录 F
    tmp = os.path.join(fdir, UPD_TMP_DIR)
    _rmtree_retry(tmp)                     # 上一次更新留下的暂存（半途失败会剩）
    if os.path.isdir(tmp):
        raise RuntimeError('上次更新的暂存目录删不掉（有文件被占用），重启后再试')
    try:
        with zipfile.ZipFile(zip_dest) as z:
            z.extractall(tmp)              # 条目名由 zipfile 自己清理（挡绝对路径 / ..）
    except Exception as e:
        _rmtree_retry(tmp)
        raise RuntimeError('解压新版失败：{}'.format(e))
    exe_name = os.path.basename(exe)
    if not os.path.isfile(os.path.join(tmp, exe_name)):
        _rmtree_retry(tmp)
        raise RuntimeError('新版压缩包里没有程序主文件 {}'.format(exe_name))
    _ver, rels = _read_manifest(os.path.join(tmp, FILE_MANIFEST))
    if rels:
        lack = [r for r in sorted(rels)
                if not os.path.isfile(os.path.join(tmp, *r.split('/')))]
        if lack:
            _rmtree_retry(tmp)
            raise RuntimeError('新版解出来少了 {} 个文件（如 {}），压缩包不完整或磁盘满了'
                               .format(len(lack), '、'.join(lack[:3])))
    return tmp


def _build_update_cmd(zip_dest):
    """生成 .upd_apply.cmd（GBK，cmd 默认码页）。新版已经解在 .upd_new 里了，这里只负责：
    等本进程(PID)退出 → robocopy 把暂存内容【合并】进程序目录（同名覆盖、多出来的不动）
    → 启动新 exe。
    用 robocopy 而不是 PowerShell：系统自带、快、天然是覆盖合并语义
    （Move-Item 遇到同名目录会直接报错，是坑）。
    【不删任何文件】：用户自己放在程序目录里的东西一律保留，新版程序启动时会按清单提示。
    失败写 .upd_fail.txt(原因码)，cmd 兜底 UNKNOWN 并重启当前 exe。
    返回 .cmd 路径；非 frozen / 路径含 % / 写盘失败 → None（调用方走手动解压指引）"""
    if not getattr(sys, 'frozen', False):
        return None
    exe = _program_target()
    fdir = os.path.dirname(exe)            # 程序目录 F
    for s in (fdir, exe):
        if _cmd_escape(s) is None:
            return None
    exe_name = os.path.basename(exe)
    # 更新完的重启要回到同一个模式：黑窗模式别被弹成 GUI
    cargs = ' --cli' if _console_mode_requested() else ''
    cmd_path = os.path.join(fdir, UPD_CMD_NAME)
    try:
        lines = [
            '@echo off',
            'chcp 936 >nul',
            'setlocal EnableExtensions',
            'set "PID={pid}"',
            'set "DIR={fdir}"',
            'set "EXE={fdir}\\{ename}"',
            'set "NEW={fdir}\\{tmpname}"',
            'set "MARK={fdir}\\{mark}"',
            'set "FIND=%WINDIR%\\System32\\find.exe"',
            'set /a N=0',
            ':wait',
            'tasklist /fi "PID eq %PID%" /nh | "%FIND%" "%PID%" >nul',
            'if errorlevel 1 goto waited',
            'timeout /t 1 /nobreak >nul',
            'set /a N+=1',
            'if %N% lss 120 goto wait',
            'taskkill /f /pid %PID% >nul 2>&1',
            'timeout /t 1 /nobreak >nul',
            ':waited',
            'taskkill /f /im "{ename}" >nul 2>&1',
            'rem robocopy 合并：同名覆盖、多出来的不动；退出码 0~7 都算成功，>=8 才是失败',
            'robocopy "%NEW%" "%DIR%" /E /MOVE /R:2 /W:1 /NFL /NDL /NJH /NJS /NP >nul',
            'if errorlevel 8 goto fail',
            'if not exist "%EXE%" goto fail_noexe',
            'if exist "%NEW%" rmdir /s /q "%NEW%" >nul 2>&1',
            'cd /d "%DIR%"',
            'start "" "%EXE%"{cargs}',
            'exit /b 0',
            ':fail',
            'echo UPD_FAIL:MOVE> "%MARK%"',
            'start "" "%EXE%"{cargs}',
            'exit /b 1',
            ':fail_noexe',
            'echo UPD_FAIL:NOEXE> "%MARK%"',
            'start "" "%EXE%"{cargs}',
            'exit /b 1',
        ]
        text = '\r\n'.join(lines).format(pid=os.getpid(), fdir=fdir, ename=exe_name,
                                         tmpname=UPD_TMP_DIR, mark=UPD_FAIL_MARK,
                                         cargs=cargs)
        with open(cmd_path, 'w', encoding='gbk') as f:
            f.write(text)
        return cmd_path
    except (OSError, UnicodeEncodeError, UnicodeDecodeError):
        try:
            os.remove(cmd_path)
        except OSError:
            pass
        return None


def _spawn_update_cmd(zip_dest, info=None):
    """frozen 全自动更新入口：先把新版解到 .upd_new（这步在本进程里做，快，
    失败时程序目录没被动过），再生成并静默拉起 .upd_apply.cmd，随后本进程应立即退出，
    cmd 等进程结束后用 robocopy 合并新版并重启。
    info 里标了 manual（作者要求手动安装）就直接不给走自动，双保险防别的入口绕过去。
    返回 (是否已接管, 失败原因)：接管了就退出进程；没接管 + 有原因就把它显示给用户，
    然后走手动解压指引"""
    if not getattr(sys, 'frozen', False):
        return False, ''
    if info and info.get('manual'):
        return False, '本版要求手动安装：请把新版压缩包解压到一个空文件夹'
    try:
        _stage_update(zip_dest)
    except RuntimeError as e:
        return False, str(e)
    cmd = None
    try:
        cmd = _build_update_cmd(zip_dest)
        if not cmd or not os.path.exists(cmd):
            return False, ''
        subprocess.Popen(['cmd.exe', '/c', cmd], cwd=os.path.dirname(cmd) or None,
                         creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0x08000000),
                         close_fds=True)
        return True, ''
    except Exception as e:
        if cmd:
            try:
                os.remove(cmd)
            except OSError:
                pass
        return False, '准备更新脚本失败：{}'.format(e)


UPD_FAIL_REASONS = {
    'EXTRACT': '新版解压失败（压缩包损坏、磁盘满了或被杀毒软件拦截）',
    'NOEXE':   '新版压缩包里缺少程序主文件',
    'CLEAN':   '更新暂存目录没清掉（有文件被占用，多为杀毒软件正在扫描）',
    'MOVE':    '新版文件铺开失败（有文件被占用，多为杀毒软件正在扫描）',
    'UNKNOWN': '原因未知',
}


def _read_update_fail_marker():
    """上次全自动更新失败的标记（.upd_fail.txt，cmd 写 UPD_FAIL:原因码）。读到即删，
    返回原因码字符串；无标记/读取失败返回 None"""
    if not getattr(sys, 'frozen', False):
        return None
    p = os.path.join(os.path.dirname(_program_target()), UPD_FAIL_MARK)
    try:
        if os.path.exists(p):
            with open(p, 'r', encoding='ascii', errors='ignore') as f:
                data = f.read().strip()
            os.remove(p)
            if ':' in data:
                return data.rsplit(':', 1)[-1].strip()
            return 'UNKNOWN'
    except OSError:
        pass
    return None


def _update_fail_msg(code):
    """失败码 → 启动提示文案（zip 保留在程序目录可手动处理）"""
    code = code or 'UNKNOWN'
    tail = ('程序已恢复运行。新版压缩包保留在程序目录，\n'
            '想手动更新就把它解压到一个【空文件夹】，用新目录里的程序。')
    if code in ('CLEAN', 'MOVE'):
        # 半更新：目录可能新旧混着，别再原地覆盖
        tail = ('程序目录可能处于半更新状态。请关掉本程序与杀毒软件的实时扫描后，\n'
                '把程序目录里的新版压缩包解压到一个【空文件夹】，用新目录里的程序，\n'
                '旧的这份目录别再用了。')
    return ('上次自动更新未完成（{}）。\n'
            '{}').format(UPD_FAIL_REASONS.get(code, code), tail)


def cli_check_update(manual=False):
    """命令行检查更新。交互询问，确认后下载并自替换，重启新进程。
    manual=False（启动自动）限时 UPD_AUTO_TIMEOUT 秒，超时强制结束并继续启动；
    两种模式都会打印检查状态。manual=True（用户输入 update）不限时。
    返回 True 表示已更新并已启动新进程（调用方应直接退出）；False 表示无需更新/失败"""
    if not _upd_configured():
        if manual:
            print('尚未配置更新仓库：填写代码顶部 GITEE_REPO / GITHUB_REPO，'
                  '或设置文件 update_gitee_repo / update_github_repo')
        return False
    if manual:
        print('正在检查更新…')
    else:
        print('启动自动检查更新（限时 {:g} 秒）… 当前版本 {}'.format(
            UPD_AUTO_TIMEOUT, APP_VERSION))
    try:
        info, note = _check_update_capped(None if manual else UPD_AUTO_TIMEOUT)
    except UpdateCheckTimeout:
        print('检查更新超时（超过 {:g} 秒），已强制结束，继续启动'.format(UPD_AUTO_TIMEOUT))
        return False
    except Exception as e:
        if manual:
            print('检查更新失败: {}'.format(e))
        else:
            print('检查更新失败: {}（已跳过，继续启动）'.format(e))
        return False
    if info is None:
        if note:
            print(note)
        elif manual:
            print('当前已是最新版本 {}'.format(APP_VERSION))
        else:
            print('已是最新版本 {}'.format(APP_VERSION))
        return False
    print()
    print('发现新版本 {}（当前 {}）'.format(info['new'], APP_VERSION))
    print('来源: {}'.format(info['url']))
    body_lines = _upd_body_lines(info)
    if body_lines:
        print()
        print('本次更新内容：')
        for ln in body_lines:
            print('    {}'.format(ln))
    auto_mode = False
    try:
        if info.get('manual'):
            # 作者在 Release 正文里标了 [MANUAL]：不给自动更新
            print()
            print('本版要求手动安装（改动较大，自动更新会留下旧文件）：')
            print('  1. 去发布页下载新版压缩包：{}'.format(_releases_page_url()))
            print('  2. 解压到一个【空文件夹】，用新目录里的程序')
            print('  3. 自己需要的文件（自己抓的 dump 等）手动拷过去')
            ans = input('只把压缩包下载到程序目录？(y/N): ').strip().lower()
            if ans not in ('y', 'yes', '是'):
                print('已取消更新')
                return False
        elif info.get('kind') == 'zip':
            ans = input('选择更新方式：\n'
                        '  a - 自动更新（覆盖为最新版并重启，约 5 秒）\n'
                        '  m - 手动更新（仅下载压缩包，自行解压替换）\n'
                        '  其他 - 取消\n> ').strip().lower()
            auto_mode = ans in ('a', 'auto', '自动')
            if not auto_mode and ans not in ('m', 'manual', '手动'):
                print('已取消更新')
                return False
        else:
            ans = input('是否下载并更新？完成后自动重启 (y/N): ').strip().lower()
            if ans not in ('y', 'yes', '是'):
                print('已取消更新')
                return False
    except (EOFError, KeyboardInterrupt):
        print()
        return False
    tgt_dir = os.path.dirname(_program_target())

    def pct(p):
        sys.stdout.write('\r下载中… {}%'.format(p))
        sys.stdout.flush()

    if info.get('kind') == 'zip':
        # 打包版更新：按用户选择走自动覆盖 或 手动解压指引
        dest = os.path.join(tgt_dir, info['fname'])
        tmp = dest + '.part'
        try:
            host, note = _download_with_fallback(info, tmp, pct_cb=pct)
            print('\r下载完成{}    '.format(note))
            print('包校验{}'.format(_verify_package(tmp, info)))
            dest = _save_downloaded(tmp, dest)
        except Exception as e:
            print()
            print('更新失败: {}'.format(e))
            return False
        print('新版压缩包已下载：{}'.format(dest))
        print()
        auto_ok, why = _spawn_update_cmd(dest, info) if auto_mode else (False, '')
        if auto_ok:
            print('自动更新中… 约需 5 秒，期间请勿手动打开程序，安装完成后自动重启')
            return True   # 退出进程，cmd 原地覆盖新版后启动
        if why:
            print('自动更新没开始：{}'.format(why))
        print('手动更新步骤：')
        print('1. 把压缩包解压到一个【空文件夹】（别覆盖旧目录）')
        print('2. 打开那个新文件夹里的程序；以后就用新目录，自己需要的文件手动拷过去')
        print('（程序即将自动退出）')
        return True   # 直接退出，释放旧程序文件占用
    tmp = os.path.join(tgt_dir, '.update_{}.part'.format(os.getpid()))
    try:
        _download_with_fallback(info, tmp, pct_cb=pct)
        print('\r包校验{}    '.format(_verify_package(tmp, info)))
    except Exception as e:
        print()
        print('更新失败: {}'.format(e))
        return False
    print('\r下载完成，正在替换程序…    ')
    try:
        _apply_install(tmp)
    except Exception as e:
        print()
        print('更新失败: {}'.format(e))
        return False
    print('已安装新版本 {}，正在重启…'.format(info['new']))
    try:
        subprocess.Popen(_relaunch_command(), cwd=tgt_dir or None, close_fds=True)
    except Exception as e:
        print('自动重启失败，请手动重新打开程序：{}'.format(e))
        return False
    time.sleep(1.0)   # 等新实例起来再退出，减少 onefile 解压/杀软扫描与旧进程清理撞车
    return True


# ---------- 输出重定向：脚本里的 print() 全部进入队列，由主线程写进日志框 ----------
class TextRedirector:
    def __init__(self, q):
        self.q = q

    def write(self, s):
        s = ANSI_RE.sub('', s)
        if s:
            self.q.put(('out', s))
        return len(s)

    def flush(self):
        pass


# ---------- 收集待修复文件（跳过规则与原脚本命令行模式一致） ----------
def collect_targets(paths):
    """返回 (待处理 ini 列表, 被跳过的 DISABLED ini 列表, 忽略项说明列表)"""
    plan, disabled, notes = [], [], []
    seen_dirs, seen_files = set(), set()

    def add_ini(fp):
        real = os.path.realpath(fp)
        if real in seen_files:
            return
        seen_files.add(real)
        plan.append(fp)

    def visit(p):
        p = os.path.abspath(p)
        if os.path.isdir(p):
            real = os.path.realpath(p)
            if real in seen_dirs:
                return
            seen_dirs.add(real)
            try:
                names = sorted(os.listdir(p))
            except OSError as e:
                notes.append('无法读取文件夹 {}: {}'.format(p, e))
                return
            for name in names:
                up = name.upper()
                if up.startswith('DESKTOP'):
                    continue
                fp = os.path.join(p, name)
                if os.path.isdir(fp):
                    visit(fp)
                elif name.lower().endswith('.ini'):
                    if up.startswith('DISABLED'):
                        disabled.append(fp)
                    else:
                        add_ini(fp)
        elif os.path.isfile(p):
            name = os.path.basename(p)
            if not name.lower().endswith('.ini'):
                notes.append('跳过非 .ini 文件: {}'.format(p))
            elif name.upper().startswith('DISABLED'):
                disabled.append(p)
            else:
                add_ini(p)
        else:
            notes.append('路径不存在: {}'.format(p))

    for p in paths:
        visit(p)
    return plan, disabled, notes


# ---------- 后台修复线程（逐文件处理，支持中途停止） ----------
def repair_worker(plan, q, cancel_event):
    total = len(plan)
    changed = nochange = failed = 0
    for idx, fp in enumerate(plan, 1):
        if cancel_event.is_set():
            q.put(('aborted',))
            return
        q.put(('prog', idx, total, fp, changed, nochange, failed))
        # 文件被实际更新时会先改名备份(DISABLED_BACKUP_*)再重写，mtime 必然变化
        try:
            m0 = os.stat(fp).st_mtime
        except OSError:
            m0 = None
        try:
            ok, hash_log = upgrade_ini(fp)
        except Exception:
            ok = False
        if ok:
            try:
                m1 = os.stat(fp).st_mtime
            except OSError:
                m1 = None
            if m0 is not None and m1 is not None and m1 != m0:
                if ok and m1 != m0 and m0 is not None:
                    q.put(('oklog', fp, hash_log))
                changed += 1
            else:
                nochange += 1
        else:
            failed += 1
    q.put(('done', changed, nochange, failed))


# ---------- 拖放支持（tkinterdnd2，已安装时可用；未安装则仅按钮选择） ----------
DROP_TOKEN = re.compile(r'\{([^{}]*)\}|([^\s{}]+)')


def split_drop_text(data):
    """解析拖放文本：带空格的路径用大括号包裹；
    括号外的空白字符（空格/制表/换行/回车）都是分隔符，兼容 tkdnd、uri-list 等不同来源布局"""
    tokens, cur, depth = [], [], 0
    for ch in data or '':
        if ch == '{':
            depth += 1
        elif ch == '}':
            depth -= 1
        if depth == 0 and ch.isspace():
            if cur:
                tokens.append(''.join(cur))
                cur = []
        else:
            cur.append(ch)
    if cur:
        tokens.append(''.join(cur))
    out = []
    for t in tokens:
        t = t.strip()
        if not t:
            continue
        if t.startswith('{') and t.endswith('}'):
            t = t[1:-1]
        t = t.strip(chr(34) + chr(39))
        if t:
            out.append(t)
    return out

def clean_gui_path(raw):
    """原命令行路径规范化 + URI 特有处理：仅当输入以 file:// 开头时做 URL 解码
    （%20 等还原为真实字符；普通输入里的 %20 是文件名的一部分，不误伤）"""
    c = _clean_path_token(raw)
    if not c:
        return None
    low = raw.strip().strip(chr(34) + chr(39)).lower()
    if low.startswith('file://') and '%' in c:
        try:
            from urllib.parse import unquote
            c = unquote(c)
        except Exception:
            pass
    return c

def resolve_spaced_tokens(tokens):
    """解析拖入片段为真实路径列表。依次尝试：
    原样存在 → URL 解码后存在 → 与后续片段按 1~4 空格拼接（含解码）后存在；
    都不行则原样保留，交由 collect 报告“路径不存在”。"""
    def exists(p):
        return os.path.isdir(p) or os.path.isfile(p)

    def decode_if_uri(p):
        low = p.strip().strip(chr(34) + chr(39)).lower()
        if low.startswith('file:') and chr(37) in p:  # %
            try:
                from urllib.parse import unquote
                return unquote(p)
            except Exception:
                return p
        return p

    out = []
    i = 0
    n = len(tokens)
    while i < n:
        tok = tokens[i]
        dec = decode_if_uri(tok)
        cand = dec if exists(dec) else tok
        if exists(cand):
            out.append(cand)
            i += 1
            continue
        joined = None
        j = i
        while j + 1 < n:
            j += 1
            for k in range(1, 5):
                seg = (chr(32) * k).join(tokens[i:j + 1])
                dseg = decode_if_uri(seg)
                if exists(dseg):
                    joined = dseg
                    break
            if joined:
                break
        if joined:
            out.append(joined)
            i = j + 1
        else:
            out.append(cand)
            i += 1
    return out

_HASH_TOKEN = re.compile(r'hash = [0-9a-f]+')   # 已更新日志中待染绿的 hash 值


def is_updated_line(line):
    """判定该日志行属于“已更新”流：实际修改了文件的证据行。
    注意 '\t保存: ' 带制表符前缀（修复器输出），无前缀的“xx已保存:”是 UI 提示，不算"""
    return ('已对该ini文件进行更新修复' in line
            or '已创建备份' in line
            or '已备份缓冲区' in line
            or '写入更新的缓冲区' in line
            or '\t保存: ' in line
            or ('更新修复' in line and '没有对' not in line))


def register_drop_targets(root, handler):
    """注册拖放：窗口及所有子控件都可接收文件/文件夹。返回成功与否"""
    try:
        from tkinterdnd2 import DND_FILES
    except Exception:
        return False
    n = 0
    stack = [root]
    while stack:
        w = stack.pop()
        try:
            w.drop_target_register(DND_FILES)
            w.dnd_bind('<<Drop>>', handler)
            n += 1
        except Exception:
            pass
        try:
            stack.extend(w.winfo_children())
        except Exception:
            pass
    return n > 0


# ================= 内嵌「索引与顶点修复」使用说明（程序目录有同名 txt 时优先读文件）
IV_HELP_TEXT = '''索引与顶点修复 —— 使用说明
================================================

怎么用（三步）
------------------------------------------------
    本工具在窗口左边竖排标签栏里，点「索引与顶点修复」就是它。

    前提：先用【版本Hash修复】把 mod 的 ini 里的 hash 更新到最新。
        没跑过这一步，本工具一个都不会修。

    第 1 步  选参照
        在「参照文件夹」下拉框里选一组（名字就是 dump 里的文件夹名，
        例如 琉音-腿、艾莲-腿）。想修哪个就选哪一组 —— 选错整包不修。
        用「通用脸部修复」模式时没有这一项，跳过。

    第 2 步  填要修的 mod
        在「修复目标路径」里填【这一个 mod 的文件夹】：点「选择路径」挑，
        或者直接把文件夹拖进窗口（拖进来的是 dump 文件夹就当参照读）。
        一次只能填一个 —— 别把整个 Mods 目录填进来，会把别的 mod 一起扫。

    第 3 步  点「▶ 开始修复」
        工具先把发现的问题列出来，弹窗让你确认，你点确认它才动手写文件。
        每个文件改之前都自动备份，改错了点「↩ 还原」按备份退回去。

    没修好？对着日志看：
        - 说没命中参照        =「参照文件夹」选错组了，换一组再来
        - 说 ini 里 hash 是旧的 = 先跑【版本Hash修复】，再跑本工具
        - 说这个网格没有 dump  = 作者还没提供参照，反馈给作者补一份
        - 说已修过、自动跳过    = 一个 buf 只修一次，正常，不用管

看不懂的词（几个常见的）
------------------------------------------------
    mod 文件夹   下载来的那个文件夹，里面有 .ini 和 .buf
    ini          mod 的文本配置；工具要改它里面的 hash 和 stride
    buf          数据文件，模型 / 贴图数据在里面
    hash         ini 里那串 8 位十六进制；游戏一更新它就会变
    dump         参照数据（作者抓的），工具拿它跟你的 mod 对着修
    参照         本次要用的那组 dump

这是什么
------------------------------------------------
    一次只修一个 mod，修这几类问题：

    一、骨骼索引（VGX）   blend.buf 里的骨骼索引被写错了
        症状：模型变形 —— 腿弯、塌陷、扭曲，但贴图正常
        已知需要修复的角色：
        1.琉音腿弯 2.艾莲腿弯 3.蕾米埃尔身体塌陷和腿扭曲
        做法：按角色表，或按 dump 参照推出来的映射，把索引逐个换对

    二、顶点格式（texcoord）  游戏更新改了顶点格式，老 mod 的 buf 布局对不上
        症状：贴图整体错乱，但模型形状完全正常
        已知需要修复的角色：
        1.脸部破碎：3.1 -> 3.2 更新里 texcoord 变过的那批网格，使用通用脸部修复可解决
        2.主要是一些角色的脸部容易出现问题
        做法：按目标表重排每个顶点的字节，并同步改 ini 里的 stride

    三、顶点上限（VertexLimitRaise）  ini 里那一节的顶点数写错 / 没写 / stride 是旧写法
        症状：模型炸开、顶点被拉到天上、顶点缓冲溢出（贴图和形状本身看着正常）
        做法：照这个网格的 buf 算真实顶点数，补上或改正 override_vertex_count；
              旧写法（92 / 96 / 76）的 override_byte_stride 一律改回 40
        只动 ini，不动 buf；顶点数不到 25000、又本来就没写数的网格不碰

    四、网格拆分修复（跟索引修复一起跑，不是单独按钮）  老 mod 的网格是一条，新版拆成了好几条分量
        症状：模型/头发/腿整块不动，或者归位了但形状对不上（那条网格绑不到新分量）
        已知需要修复的角色：
        1.铃-原皮 2.铃-泳装
        做法：按本次参照 dump 的各分量，把老的一条网格按顶点位置切开，每件写自己的
              Position/Texcoord/Blend/IB，绑该分量的 hash，并补顶点上限；原网格没对应
              的地方并进主件；没拆出东西的分量不动（游戏照原样画）
        推不出来（配不上 / texcoord 布局推不出 / 骨索引推不出）就整单不修

    五、掐掉多余的那几笔（跟"索引与顶点修复"一起跑）  原版分量 / 索引段多出来的
        症状：同一块地方画两遍（耳坠、发夹这种小件最容易看出来）、或者身体某处
              糊成一团（mod 那条 IB 第 2 段拿 mod 的顶点去画原版的索引）
        做法：只按本次参照 dump + mod 自己的 ini 判两件事 ——
              ① 某个分量的五个 hash 在 mod 的 ini 里一个都没出现、而它的顶点有
                 30% 以上能被 mod 的网格盖住 -> mod 画的就是它，出一节 handling = skip
              ② mod 认了这条分量（有 match_first_index 的节）但 dump 里它还有第 2 段
                 起、ini 里没人 match 的 -> 出 hash + match_first_index = 那一段 的 skip
        只动 ini（备份 .texfmt.bak），掐了哪几笔都打在报告里；分量盖不住就跳过

    这几步一起跑，哪个命中修哪个；都没命中就什么都不做。

两种模式（面板最上面那排按钮切）
------------------------------------------------
    索引与顶点修复（默认）
        上面五类一起跑：骨骼索引、顶点格式、顶点上限、掐笔、网格拆分。
        按“参照文件夹”里选的那组 dump 走，要先选参照。
        网格拆分没有单独按钮：跑完前面几步会自动接着拆，
        不需要拆的网格会自己跳过；参照组不在拆分名单（铃-原皮 / 铃-泳装）时也跳过。

        网格拆分具体做什么：
        老 mod 的网格是旧版的一条、新版把那条拆成了好几条分量时用
        （例：铃 3.0 起身体拆成上半身 / 耳环 / 腿；老的"头发"那一槽里其实是头发+腿+鞋）：
        按"参照文件夹"那组 dump 的各分量，把老的一条网格按顶点位置切开，
        每件写自己的 Position/Texcoord/Blend/IB、绑该分量的 hash、补顶点上限。
        主件 = mod 的 IB hash 现在指向的那个分量；小的、没归属的并进主件（不丢几何）；
        没拆出东西的分量不动，游戏照原样画。推不出来（配不上 / texcoord 布局推不出 /
        骨索引推不出）就整单不修，会写清卡在哪。
        拆出来的文件记在 mod 目录的 split_created.json，点"还原"会删掉它们。

    通用脸部修复
        3.1 -> 3.2 更新里 texcoord 变过的那批网格，只有一种变化，写死在程序里，
        不用填格式，也不用选参照：

            texcoord 里最前面那块顶点 COLOR 4 字节（R8G8B8A8_UNORM）
            -> 4 个 float，每顶点多 12 字节（旧 36 -> 新 48 字节/顶点）

        认的是内嵌的 53 个网格 / 46 个角色的名单（Hash变动日志里“更新后”那些 hash）。
        点“通用脸部修复”进去之后：dump 参照 / 参照文件夹两行收起来（这个模式不看参照），
        主按钮变成“▶ 开始通用脸部修复”；路径栏、日志、还原都是同一套。
        只动 texcoord buf 和 ini 里那行 stride，骨骼索引（VGX）不碰。
        想回去点“索引与顶点修复”。

        老 mod 的 texcoord 比游戏少几块时（2024 年那批只有 2 条 UV，现在 4 条），
        buf 大小对不上 36 —— 只要 dump 里正好有这个网格，就按 dump 的元素表
        + buf 实际字节推出每块落在哪，缺的块补 0（推不出就说跳过，不乱修；
        跳过时会把卡在哪说清：dump 缺 -*Texcoord.buf / 值域对不上 / 形状不对）。
        推出来时，如果 dump 里这个网格绑了不止一张贴图，会多提醒一句 ——
        那种网格补 0 会让那层贴图失效。

参照文件夹怎么选 (选错 = 整包不修)
------------------------------------------------
    开修之前先拿 mod 的 ini 里的 hash 跟本次这组参照对一次：

        把这组 dump 里出现过的 hash 全收成一个集合
        （每个网格各算 Texcoord / Blend / Position 三个），
        mod 的 ini 里【命中任意一个】就够了 —— 每组的 hash
        都不一样，命中一个就说明这个 mod 和参照是同一组。

    命中   ->  认定同组，这个 mod 该怎么修怎么修
    没命中 ->  整包不处理，日志写清楚，一个文件都不动

    日志里会写明命中的是哪个 hash，例如：

        参照比对：ini 里的 hash ff36809b 命中本次参照【琉音(2)】

    想修哪个网格，就把“参照文件夹”换成它对应的那一组。
    前提还是那条：mod 的 ini 里 hash 要是当前版本（先跑版本Hash修复），
    否则可能一个都对不上，被当成别的组整包挡下来。

    例外只有一种：程序目录 dump\\ 里一个数据都没有的时候，没有参照可核对，
    这时只走表，不做参照限制。

为什么不按角色归类
------------------------------------------------
    分组按 dump 里的【文件夹名】走，不按“角色”把同角色的几组并在一起。

    因为参照是跟着修复进度走的：一组修过了，它的 buf 就跟没修过的那组
    不是一个状态。合并成一个「琉音」的话，选「琉音」会把已经修过的
    「琉音-腿」一起带上 —— 修「琉音-脸」的时候顺手又修一遍腿，
    已经修好的那个网格被修第二遍。

    所以 dump\\ 里一个文件夹就是一组，修过的那组要么单独选，
    要么直接移出 dump\\ 别再参与。

dump 参照
------------------------------------------------
    自动读的位置（没有的话程序不会替你建，提示一下就完事）：
        程序目录下的 dump\\          （exe 旁边；源码跑时 = 源码旁边）
        程序目录的上一级\\dump\\     （源码放在 py代码\\ 这类子目录里时用这个）
        索引与顶点修复工具\\dump\\   （旧位置，有数据就用）
    也可以点“选择 dump 文件夹”或直接把 dump 文件夹拖进窗口
    （有 .json、没有 .ini 会被认出来），选过的目录会记住，下次启动自动读。

    自己加的 dump 只能放程序目录【外面】：程序启动时会检查程序目录，
    发现不属于本程序的文件就不让用。所以别往上面这些 dump\\ 里放东西，
    找个程序目录外的地方新建文件夹放好，再用“选择 dump 文件夹”选它。

    dump 里缺哪个角色 / 哪个网格，反馈给作者补一份就行 —— 抓 dump 是作者的事。

    自己抓的 dump 想推 VGX 表（新旧两版同一个部位），用 查找工具\两版推VGX表，
    它出的是能直接贴进本工具 VGX_CHARACTERS 的代码块 —— 本工具不自己推，
    保持精简。

问什么答什么
------------------------------------------------
    表里和 dump 里都能修同一个网格  ->  问一次用哪边
        （表 = 人手填过，可控；dump = 游戏当前状态，最新）
    表里没有、只有 dump 能自动推    ->  问一次要不要修
    写入前                          ->  确认一次

    确认框弹出之前，工具不会改动任何文件。

还原
------------------------------------------------
    切到本标签页，点“↩ 还原”，按备份把文件退回去（会先列出要还原哪些）。
    掐笔追加的节也走这份 ini 备份（.texfmt.bak）退回。

    备份长这样：
        VGX 部分：  xxx.vgx_BACKUP.buf              原 buf
                    xxx.vgx_REMAP_APPLIED.empty     已修标记
        格式部分：  xxx.texfmt_BACKUP.buf           原 buf
                    xxx.texfmt.bak                  ini 原文件（格式 / 顶点上限这两项共用）
                    xxx.texfmt_DONE.empty           已修标记
                    （旧工具留下的 .tex48_BACKUP.buf / .tex48.bak 还原时也认）

    只认本工具的备份。
    版本Hash修复留下的改名式备份（DISABLED_BACKUP_*.ini）不用手动改名：
    切到【版本Hash修复】标签，点那一行里的“↩ 还原”，
    每一项默认按最早的一份（最接近原版）退回，用掉的那份备份会删掉。
    那个还原只碰 ini，不动缓冲区；一次只放一个 mod，
    路径只认“手动修复路径”那一栏，默认修复路径不参与。
    还原前会把当前 ini 按备份规则另存一份，所以还原本身也能再还原。

注意事项
    - 一个 buf 不要跑两次（有备份 / 标记的会自动跳过）
    - 版本更新后：先跑【版本Hash修复】把 ini 里的 hash 更新到最新，再跑本工具
    - 工具会提醒“看着是旧格式、但没被处理”的 texcoord，并说明原因：
          ① mod 的 ini 里 hash 还是旧的   -> 先跑版本Hash修复
          ② 这个网格作者还没提供 dump    -> 反馈给作者补一份

给作者（加新角色 / 新网格）
------------------------------------------------
    两张表在源码的内嵌模块“索引与顶点修复工具”里：
        VGX_CHARACTERS    骨骼索引映射。
                          hashes 填该角色 Position 节的 hash（ini 里带 vb2 = ResourcexxxBlend 的那节）；
                          old / new 用 查找VGX映射工具 生成。
        TEXCOORD_TARGETS  顶点格式重排。
                          hash 用【当前版本】的 texcoord hash；
                          old_format / new_format 用 查找Texcoord映射工具 生成；
                          blend_hash 选填，填了反推顶点数更稳。

    同一份代码在 索引与顶点修复工具\\索引与顶点修复工具.py，改一边记得同步另一边。
    说明文字本文件即可：程序目录放一份“索引与顶点修复使用说明.txt”会覆盖上面的内嵌内容。

================================================
'''

# =====================================================================
# 内嵌模块：索引与顶点修复工具（VGX 骨骼索引 + texcoord 顶点格式）
#   —— 原独立脚本 索引与顶点修复工具/索引与顶点修复工具.py 的完整实现。
#      独立脚本本体保持原样，两边互不影响；改这边时记得同步那边。
